insert into public.questions (id, region_id, category_id, kind, format, difficulty, is_vote, text, options, explanation, source, audience) values
('nin-ani-001', null, 'animales', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cuál es el animal terrestre más grande del mundo?', '["El elefante africano", "La jirafa", "El rinoceronte", "El hipopótamo"]'::jsonb, 'El elefante africano puede pesar más de seis toneladas.', null, 'KIDS'),
('nin-ani-002', null, 'animales', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cuántas patas tiene una araña?', '["Seis", "Ocho", "Diez", "Cuatro"]'::jsonb, 'Las arañas tienen ocho patas; los insectos tienen seis.', null, 'KIDS'),
('nin-ani-003', null, 'animales', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿A qué animal se le llama «el rey de la selva»?', '["Al tigre", "Al oso", "Al león", "Al lobo"]'::jsonb, 'Al león se le dice así, aunque en realidad vive en la sabana africana.', null, 'KIDS'),
('nin-ani-004', null, 'animales', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cuál es el animal más alto del mundo?', '["El elefante", "El camello", "El avestruz", "La jirafa"]'::jsonb, 'Gracias a su cuello tan largo, la jirafa puede medir más de cinco metros.', null, 'KIDS'),
('nin-ani-005', null, 'animales', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué animal produce la miel?', '["La abeja", "La mariposa", "La hormiga", "La mosca"]'::jsonb, 'Las abejas hacen la miel con el néctar de las flores.', null, 'KIDS'),
('nin-ani-006', null, 'animales', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿En qué se convierte un renacuajo cuando crece?', '["En un pez", "En una rana", "En una lagartija", "En una tortuga"]'::jsonb, 'El renacuajo nace en el agua y poco a poco le salen patas hasta convertirse en rana.', null, 'KIDS'),
('nin-ani-007', null, 'animales', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué come principalmente el oso panda?', '["Pescado", "Miel", "Bambú", "Frutas"]'::jsonb, 'El panda pasa gran parte del día comiendo bambú.', null, 'KIDS'),
('nin-ani-008', null, 'animales', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Cuál de estos animales es un mamífero?', '["El tiburón", "La tortuga", "El pingüino", "La ballena"]'::jsonb, 'La ballena respira aire con pulmones y alimenta a sus crías con leche.', null, 'KIDS'),
('nin-ani-009', null, 'animales', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Cuál es el ave más grande del mundo?', '["El avestruz", "El cóndor", "El águila", "El pavo real"]'::jsonb, 'El avestruz puede medir más de dos metros, aunque no puede volar.', null, 'KIDS'),
('nin-ani-010', null, 'animales', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cómo se llama la cría de la vaca?', '["Potro", "Ternero", "Cordero", "Cachorro"]'::jsonb, 'La cría de la vaca es el ternero; el potro es la cría del caballo y el cordero, la de la oveja.', null, 'KIDS'),
('nin-ani-011', null, 'animales', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué animal cambia de color?', '["El perro", "El caballo", "El camaleón", "El conejo"]'::jsonb, 'El camaleón cambia el color de su piel, por ejemplo según la temperatura o su estado de ánimo.', null, 'KIDS'),
('nin-ani-012', null, 'animales', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Qué ave aparece en el escudo de Colombia?', '["El tucán", "El loro", "El colibrí", "El cóndor"]'::jsonb, 'El cóndor de los Andes corona el escudo de Colombia.', null, 'KIDS'),
('nin-ani-013', null, 'animales', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Cuántas patas tiene un insecto?', '["Seis", "Ocho", "Cuatro", "Diez"]'::jsonb, 'Todos los insectos, como las hormigas o las abejas, tienen seis patas.', null, 'KIDS'),
('nin-ani-014', null, 'animales', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué animal tiene una trompa larga?', '["La jirafa", "El elefante", "El cocodrilo", "La cebra"]'::jsonb, 'El elefante usa su trompa para respirar, oler, beber agua y agarrar cosas.', null, 'KIDS'),
('nin-ani-015', null, 'animales', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Dónde viven casi todos los pingüinos?', '["En el Polo Norte", "En la selva", "En el hemisferio sur", "En el desierto del Sahara"]'::jsonb, 'Casi todos los pingüinos viven en el hemisferio sur, por ejemplo en la Antártida. En el Polo Norte no hay pingüinos.', null, 'KIDS'),
('nin-ani-016', null, 'animales', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Cuál es el animal más rápido en tierra?', '["El caballo", "El león", "La liebre", "El guepardo"]'::jsonb, 'El guepardo puede correr a más de 100 kilómetros por hora en carreras cortas.', null, 'KIDS'),
('nin-cie-001', null, 'ciencia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿En qué planeta vivimos?', '["Marte", "La Tierra", "Venus", "Júpiter"]'::jsonb, 'Vivimos en la Tierra, el tercer planeta desde el Sol.', null, 'KIDS'),
('nin-cie-002', null, 'ciencia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, 'Además de agua, ¿qué necesitan las plantas para crecer?', '["Oscuridad", "Ruido", "Luz del sol", "Hielo"]'::jsonb, 'Las plantas usan la luz del sol para fabricar su alimento.', null, 'KIDS'),
('nin-cie-003', null, 'ciencia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Cuál es el planeta más grande del sistema solar?', '["Saturno", "Neptuno", "La Tierra", "Júpiter"]'::jsonb, 'Júpiter es tan grande que dentro de él cabrían más de mil Tierras.', null, 'KIDS'),
('nin-cie-004', null, 'ciencia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué estrella nos da luz y calor durante el día?', '["El Sol", "La Luna", "Marte", "La estrella polar"]'::jsonb, 'El Sol es la estrella más cercana a la Tierra.', null, 'KIDS'),
('nin-cie-005', null, 'ciencia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿En qué se convierte el agua cuando se congela?', '["En vapor", "En hielo", "En arena", "En aire"]'::jsonb, 'Cuando el agua se enfría mucho se vuelve sólida: es el hielo.', null, 'KIDS'),
('nin-cie-006', null, 'ciencia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Cuántos colores se cuentan tradicionalmente en el arcoíris?', '["Cinco", "Seis", "Siete", "Ocho"]'::jsonb, 'Rojo, naranja, amarillo, verde, azul, añil y violeta.', null, 'KIDS'),
('nin-cie-007', null, 'ciencia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué órgano bombea la sangre por todo el cuerpo?', '["Los pulmones", "El estómago", "El cerebro", "El corazón"]'::jsonb, 'El corazón late todo el tiempo para mover la sangre por el cuerpo.', null, 'KIDS'),
('nin-cie-008', null, 'ciencia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Con qué parte del cuerpo olemos?', '["La nariz", "Los oídos", "Los ojos", "La lengua"]'::jsonb, 'El olfato está en la nariz.', null, 'KIDS'),
('nin-cie-009', null, 'ciencia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Cuántos dientes de leche tiene normalmente un niño?', '["Diez", "Veinte", "Treinta y dos", "Cuarenta"]'::jsonb, 'Los niños tienen 20 dientes de leche, que luego cambian por los dientes permanentes.', null, 'KIDS'),
('nin-cie-010', null, 'ciencia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué gas necesitamos respirar para vivir?', '["Dióxido de carbono", "Helio", "Oxígeno", "Humo"]'::jsonb, 'Al respirar tomamos oxígeno del aire.', null, 'KIDS'),
('nin-cie-011', null, 'ciencia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué gira alrededor de la Tierra y vemos de noche en el cielo?', '["El Sol", "Marte", "Venus", "La Luna"]'::jsonb, 'La Luna es el satélite natural de la Tierra.', null, 'KIDS'),
('nin-cul-001', null, 'cultura', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué color sale al mezclar azul y amarillo?', '["Verde", "Morado", "Naranja", "Rosado"]'::jsonb, 'Azul y amarillo dan verde.', null, 'KIDS'),
('nin-cul-002', null, 'cultura', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué color sale al mezclar rojo y amarillo?', '["Verde", "Naranja", "Morado", "Gris"]'::jsonb, 'Rojo y amarillo dan naranja.', null, 'KIDS'),
('nin-geo-001', null, 'geografia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cuál es la capital de Colombia?', '["Medellín", "Cali", "Bogotá", "Barranquilla"]'::jsonb, 'Bogotá es la capital de Colombia.', null, 'KIDS'),
('nin-geo-002', null, 'geografia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿De qué colores es la bandera de Colombia?', '["Rojo y blanco", "Verde y blanco", "Azul y rojo", "Amarillo, azul y rojo"]'::jsonb, 'La bandera de Colombia es amarilla, azul y roja.', null, 'KIDS'),
('nin-geo-003', null, 'geografia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Cuál es el océano más grande del planeta?', '["El Pacífico", "El Atlántico", "El Índico", "El Ártico"]'::jsonb, 'El océano Pacífico es el más grande y el más profundo.', null, 'KIDS'),
('nin-geo-004', null, 'geografia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Qué dos océanos bañan las costas de Colombia?', '["El Índico y el Pacífico", "El Pacífico y el Atlántico", "El Ártico y el Atlántico", "El Índico y el Ártico"]'::jsonb, 'Colombia tiene costa en el océano Pacífico y en el mar Caribe, que forma parte del océano Atlántico.', null, 'KIDS'),
('nin-geo-005', null, 'geografia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿En qué continente está Colombia?', '["Europa", "África", "América", "Asia"]'::jsonb, 'Colombia está en América del Sur.', null, 'KIDS'),
('nin-geo-006', null, 'geografia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cómo se llama un lugar donde casi nunca llueve?', '["Una selva", "Un páramo", "Un glaciar", "Un desierto"]'::jsonb, 'En los desiertos llueve muy poco, como en el desierto de La Guajira.', null, 'KIDS'),
('nin-geo-007', null, 'geografia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Cuál es el país más grande del mundo?', '["Rusia", "China", "Brasil", "Estados Unidos"]'::jsonb, 'Rusia es el país con más territorio del mundo.', null, 'KIDS'),
('nin-geo-008', null, 'geografia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Cuál es la montaña más alta del mundo?', '["El Aconcagua", "El Everest", "El Kilimanjaro", "El Nevado del Ruiz"]'::jsonb, 'El monte Everest, en Asia, mide unos 8.849 metros.', null, 'KIDS'),
('nin-geo-009', null, 'geografia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿En qué país están las famosas pirámides de Guiza?', '["México", "Perú", "Egipto", "India"]'::jsonb, 'Las pirámides de Guiza están en Egipto y tienen más de 4.000 años.', null, 'KIDS'),
('nin-dep-001', null, 'deportes', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cuántos jugadores tiene cada equipo de fútbol en la cancha?', '["Nueve", "Diez", "Doce", "Once"]'::jsonb, 'Cada equipo juega con once jugadores, contando al arquero.', null, 'KIDS'),
('nin-dep-002', null, 'deportes', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, 'En el fútbol, ¿con qué no pueden tocar el balón los jugadores, salvo el arquero?', '["Con las manos", "Con la cabeza", "Con el pecho", "Con los pies"]'::jsonb, 'Solo el arquero puede usar las manos, y únicamente dentro de su área.', null, 'KIDS'),
('nin-dep-003', null, 'deportes', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿En qué deporte se usa una raqueta y una pelota amarilla pequeña?', '["Baloncesto", "Tenis", "Natación", "Ciclismo"]'::jsonb, 'En el tenis se golpea la pelota con una raqueta por encima de una red.', null, 'KIDS'),
('nin-dep-004', null, 'deportes', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Cada cuántos años se juega el Mundial de fútbol?', '["Cada año", "Cada dos años", "Cada cuatro años", "Cada diez años"]'::jsonb, 'La Copa Mundial de la FIFA se juega cada cuatro años.', null, 'KIDS'),
('nin-dep-005', null, 'deportes', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Qué deporte practica Mariana Pajón, campeona olímpica colombiana?', '["Atletismo", "Natación", "Patinaje", "BMX"]'::jsonb, 'Mariana Pajón ganó la medalla de oro en BMX en los Juegos Olímpicos de 2012 y de 2016.', null, 'KIDS'),
('nin-dep-006', null, 'deportes', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿En qué deporte hay que meter el balón por un aro?', '["Baloncesto", "Voleibol", "Béisbol", "Golf"]'::jsonb, 'En el baloncesto se anota encestando el balón en el aro.', null, 'KIDS'),
('nin-dep-007', null, 'deportes', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cuántos anillos tiene el símbolo de los Juegos Olímpicos?', '["Cuatro", "Cinco", "Seis", "Siete"]'::jsonb, 'Los cinco anillos representan la unión de los continentes.', null, 'KIDS'),
('nin-dep-008', null, 'deportes', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué se necesita para practicar ciclismo?', '["Patines", "Una raqueta", "Una bicicleta", "Un balón"]'::jsonb, 'El ciclismo es el deporte de la bicicleta.', null, 'KIDS'),
('nin-mus-001', null, 'musica', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Cuántas cuerdas tiene normalmente una guitarra?', '["Cuatro", "Cinco", "Doce", "Seis"]'::jsonb, 'La guitarra más común tiene seis cuerdas.', null, 'KIDS'),
('nin-mus-002', null, 'musica', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué instrumento tiene teclas blancas y negras?', '["El piano", "La flauta", "El tambor", "El violín"]'::jsonb, 'El piano tiene teclas blancas y negras que se tocan con los dedos.', null, 'KIDS'),
('nin-mus-003', null, 'musica', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué instrumento es típico del vallenato?', '["La trompeta", "El acordeón", "El arpa", "El saxofón"]'::jsonb, 'El acordeón, la caja y la guacharaca son los instrumentos del vallenato.', null, 'KIDS'),
('nin-mus-004', null, 'musica', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué instrumento se toca golpeándolo con las manos o con palos?', '["La flauta", "La guitarra", "El tambor", "El violín"]'::jsonb, 'El tambor es un instrumento de percusión: suena al golpearlo.', null, 'KIDS'),
('nin-mus-005', null, 'musica', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cuál de estos instrumentos se toca soplando?', '["La guitarra", "El piano", "El tambor", "La flauta"]'::jsonb, 'La flauta suena cuando soplamos aire por ella.', null, 'KIDS'),
('nin-cur-001', null, 'curiosidades', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cuántos días tiene una semana?', '["Siete", "Cinco", "Seis", "Diez"]'::jsonb, 'La semana tiene siete días, de lunes a domingo.', null, 'KIDS'),
('nin-cur-002', null, 'curiosidades', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cuántos meses tiene un año?', '["Diez", "Doce", "Once", "Catorce"]'::jsonb, 'El año tiene doce meses, de enero a diciembre.', null, 'KIDS'),
('nin-cur-003', null, 'curiosidades', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué mes viene después de marzo?', '["Mayo", "Febrero", "Abril", "Junio"]'::jsonb, 'Después de marzo viene abril.', null, 'KIDS'),
('nin-num-001', null, 'numeros', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cuántos lados tiene un triángulo?', '["Cuatro", "Cinco", "Dos", "Tres"]'::jsonb, '«Tri» significa tres: el triángulo tiene tres lados.', null, 'KIDS'),
('nin-num-002', null, 'numeros', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cuánto es 5 + 3?', '["8", "7", "9", "6"]'::jsonb, '5 + 3 = 8.', null, 'KIDS'),
('nin-num-003', null, 'numeros', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cuántos minutos tiene una hora?', '["Cien", "Sesenta", "Treinta", "Cuarenta"]'::jsonb, 'Una hora tiene 60 minutos.', null, 'KIDS'),
('nin-num-004', null, 'numeros', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Cuánto es 3 × 4?', '["7", "10", "12", "14"]'::jsonb, '3 × 4 = 12.', null, 'KIDS'),
('nin-num-005', null, 'numeros', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cuántos lados tiene un cuadrado?', '["Tres", "Cinco", "Seis", "Cuatro"]'::jsonb, 'El cuadrado tiene cuatro lados iguales.', null, 'KIDS'),
('nin-num-006', null, 'numeros', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cuál es la mitad de 10?', '["5", "2", "4", "20"]'::jsonb, '10 dividido entre 2 es 5.', null, 'KIDS'),
('nin-num-007', null, 'numeros', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cuántas horas tiene un día?', '["Doce", "Veinticuatro", "Treinta", "Diez"]'::jsonb, 'Un día completo tiene 24 horas.', null, 'KIDS'),
('nin-num-008', null, 'numeros', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué número viene después del 99?', '["98", "909", "100", "110"]'::jsonb, 'Después del 99 viene el 100.', null, 'KIDS'),
('nin-num-009', null, 'numeros', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Cuál es el doble de 6?', '["8", "10", "3", "12"]'::jsonb, 'El doble de 6 es 6 + 6 = 12.', null, 'KIDS'),
('nin-cin-001', null, 'cine', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿De qué color es Bob Esponja?', '["Amarillo", "Azul", "Verde", "Rosado"]'::jsonb, 'Bob Esponja es una esponja de mar amarilla.', null, 'KIDS'),
('nin-cin-002', null, 'cine', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿En qué película de Disney aparece la familia Madrigal, que vive en Colombia?', '["Coco", "Encanto", "Frozen", "Moana"]'::jsonb, '«Encanto» (2021) cuenta la historia de la familia Madrigal en un pueblo de Colombia.', null, 'KIDS'),
('nin-cin-003', null, 'cine', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cómo se llama el muñeco de nieve de la película «Frozen»?', '["Sven", "Kristoff", "Olaf", "Hans"]'::jsonb, 'Olaf es el muñeco de nieve que sueña con el verano.', null, 'KIDS'),
('nin-cin-004', null, 'cine', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué tipo de animal es Nemo en «Buscando a Nemo»?', '["Un tiburón", "Una tortuga", "Un pulpo", "Un pez payaso"]'::jsonb, 'Nemo es un pez payaso, naranja con rayas blancas.', null, 'KIDS'),
('nin-cin-005', null, 'cine', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Cómo se llama el vaquero de juguete de «Toy Story»?', '["Woody", "Buzz", "Rex", "Andy"]'::jsonb, 'Woody es el vaquero; Buzz Lightyear es el astronauta.', null, 'KIDS'),
('nin-cin-006', null, 'cine', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué personaje dice «¡Hasta el infinito y más allá!»?', '["Woody", "Buzz Lightyear", "Mickey Mouse", "Shrek"]'::jsonb, 'Es la frase famosa de Buzz Lightyear en «Toy Story».', null, 'KIDS'),
('nin-cin-007', null, 'cine', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿De qué color es el ogro Shrek?', '["Azul", "Rojo", "Verde", "Morado"]'::jsonb, 'Shrek es un ogro verde que vive en un pantano.', null, 'KIDS'),
('nin-cin-008', null, 'cine', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué animal es Mickey?', '["Un perro", "Un gato", "Un pato", "Un ratón"]'::jsonb, 'Mickey Mouse es un ratón; «mouse» significa ratón en inglés.', null, 'KIDS'),
('nin-his-001', null, 'historia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Quién llegó a América en 1492 con tres barcos?', '["Cristóbal Colón", "Simón Bolívar", "Antonio Nariño", "Francisco de Paula Santander"]'::jsonb, 'Cristóbal Colón llegó a América el 12 de octubre de 1492 con la Niña, la Pinta y la Santa María.', null, 'KIDS'),
('nin-his-002', null, 'historia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Qué día se celebra la independencia de Colombia?', '["El 12 de octubre", "El 20 de julio", "El 25 de diciembre", "El 1 de enero"]'::jsonb, 'El 20 de julio de 1810 ocurrió el Grito de Independencia en Bogotá.', null, 'KIDS'),
('nin-his-003', null, 'historia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿A quién se le conoce como «el Libertador»?', '["A Francisco de Paula Santander", "A Policarpa Salavarrieta", "A Simón Bolívar", "A Gabriel García Márquez"]'::jsonb, 'Simón Bolívar dirigió la independencia de varios países de América del Sur, entre ellos Colombia.', null, 'KIDS'),
('nin-tec-001', null, 'tecnologia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Qué inventaron los hermanos Wright, que volaron por primera vez en 1903?', '["El carro", "El tren", "El teléfono", "El avión"]'::jsonb, 'Los hermanos Wright hicieron el primer vuelo con un avión a motor en 1903.', null, 'KIDS'),
('nin-tec-002', null, 'tecnologia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué aparato usamos para hablar con alguien que está lejos?', '["El teléfono", "La nevera", "La lavadora", "La licuadora"]'::jsonb, 'Con el teléfono podemos hablar con personas que están lejos.', null, 'KIDS'),
('nin-tec-003', null, 'tecnologia', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué parte del computador usamos para escribir letras?', '["El monitor", "El teclado", "El parlante", "La impresora"]'::jsonb, 'El teclado tiene una tecla para cada letra.', null, 'KIDS'),
('nin-cul-003', null, 'cultura', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Qué escritor colombiano escribió «Cien años de soledad»?', '["Rafael Pombo", "Jorge Isaacs", "Gabriel García Márquez", "Álvaro Mutis"]'::jsonb, 'Gabriel García Márquez la publicó en 1967 y ganó el Premio Nobel de Literatura en 1982.', null, 'KIDS'),
('nin-cul-004', null, 'cultura', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'MEDIUM', false, '¿Quién escribió «Rin Rin Renacuajo» y «La pobre viejecita»?', '["Gabriel García Márquez", "Jorge Isaacs", "José Asunción Silva", "Rafael Pombo"]'::jsonb, 'Rafael Pombo es el autor colombiano de muchos cuentos y poemas para niños.', null, 'KIDS'),
('nin-cur-004', null, 'curiosidades', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué fruta es amarilla, alargada y se pela antes de comerla?', '["El banano", "La fresa", "La uva", "El limón"]'::jsonb, 'El banano tiene una cáscara amarilla que se quita antes de comerlo.', null, 'KIDS'),
('nin-cul-005', null, 'cultura', 'OBJECTIVE', 'MULTIPLE_CHOICE', 'EASY', false, '¿Qué comida colombiana se hace con masa de maíz, es redonda y se asa?', '["El ajiaco", "La arepa", "La bandeja paisa", "El sancocho"]'::jsonb, 'La arepa se hace con masa de maíz y se come en todo el país.', null, 'KIDS'),
('nin-cie-012', null, 'ciencia', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'El Sol es una estrella.', '["Verdadero", "Falso"]'::jsonb, 'El Sol es una estrella, la más cercana a la Tierra.', null, 'KIDS'),
('nin-ani-017', null, 'animales', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'Los peces respiran con pulmones.', '["Verdadero", "Falso"]'::jsonb, 'Los peces respiran con branquias, que toman el oxígeno del agua.', null, 'KIDS'),
('nin-cie-013', null, 'ciencia', 'OBJECTIVE', 'TRUE_FALSE', 'MEDIUM', false, 'La Luna tiene luz propia.', '["Verdadero", "Falso"]'::jsonb, 'La Luna no brilla sola: refleja la luz del Sol.', null, 'KIDS'),
('nin-ani-018', null, 'animales', 'OBJECTIVE', 'TRUE_FALSE', 'MEDIUM', false, 'Las ballenas son peces.', '["Verdadero", "Falso"]'::jsonb, 'Las ballenas son mamíferos: respiran aire y toman leche de su mamá.', null, 'KIDS'),
('nin-cie-014', null, 'ciencia', 'OBJECTIVE', 'TRUE_FALSE', 'MEDIUM', false, 'El agua hierve a 100 grados Celsius al nivel del mar.', '["Verdadero", "Falso"]'::jsonb, 'A nivel del mar el agua hierve a 100 °C; en lugares altos, como Bogotá, hierve un poco antes.', null, 'KIDS'),
('nin-ani-019', null, 'animales', 'OBJECTIVE', 'TRUE_FALSE', 'MEDIUM', false, 'Los murciélagos son mamíferos que pueden volar.', '["Verdadero", "Falso"]'::jsonb, 'El murciélago es el único mamífero que vuela de verdad.', null, 'KIDS'),
('nin-cur-005', null, 'curiosidades', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'Un año tiene 365 días, menos los bisiestos, que tienen 366.', '["Verdadero", "Falso"]'::jsonb, 'Cada cuatro años, más o menos, febrero tiene 29 días y el año tiene 366.', null, 'KIDS'),
('nin-geo-010', null, 'geografia', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'Bogotá es la capital de Colombia.', '["Verdadero", "Falso"]'::jsonb, 'Bogotá es la capital del país.', null, 'KIDS'),
('nin-ani-020', null, 'animales', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'Las vacas ponen huevos.', '["Verdadero", "Falso"]'::jsonb, 'Las vacas son mamíferos: sus terneros nacen de la barriga de la mamá.', null, 'KIDS'),
('nin-dep-009', null, 'deportes', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'Un balón de fútbol es cuadrado.', '["Verdadero", "Falso"]'::jsonb, 'El balón de fútbol es redondo.', null, 'KIDS'),
('nin-cie-015', null, 'ciencia', 'OBJECTIVE', 'TRUE_FALSE', 'MEDIUM', false, 'El arcoíris aparece cuando la luz del sol atraviesa gotas de agua.', '["Verdadero", "Falso"]'::jsonb, 'Las gotas separan la luz del sol en sus colores.', null, 'KIDS'),
('nin-ani-021', null, 'animales', 'OBJECTIVE', 'TRUE_FALSE', 'MEDIUM', false, 'Las arañas son insectos.', '["Verdadero", "Falso"]'::jsonb, 'Las arañas son arácnidos: tienen ocho patas, no seis.', null, 'KIDS'),
('nin-ani-022', null, 'animales', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'Los pingüinos pueden volar.', '["Verdadero", "Falso"]'::jsonb, 'Los pingüinos son aves, pero no vuelan: usan sus alas para nadar.', null, 'KIDS'),
('nin-cie-016', null, 'ciencia', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'Las personas tenemos dos pulmones.', '["Verdadero", "Falso"]'::jsonb, 'Tenemos un pulmón a cada lado del pecho.', null, 'KIDS'),
('nin-num-010', null, 'numeros', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'El 10 es un número par.', '["Verdadero", "Falso"]'::jsonb, 'El 10 se puede dividir entre 2 sin que sobre nada.', null, 'KIDS'),
('nin-num-011', null, 'numeros', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, '7 + 2 es igual a 10.', '["Verdadero", "Falso"]'::jsonb, '7 + 2 = 9.', null, 'KIDS'),
('nin-geo-011', null, 'geografia', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'Colombia tiene costa en el mar Caribe y en el océano Pacífico.', '["Verdadero", "Falso"]'::jsonb, 'Colombia es el único país de América del Sur con costa en los dos.', null, 'KIDS'),
('nin-ani-023', null, 'animales', 'OBJECTIVE', 'TRUE_FALSE', 'MEDIUM', false, 'Los tiburones son mamíferos.', '["Verdadero", "Falso"]'::jsonb, 'Los tiburones son peces.', null, 'KIDS'),
('nin-cie-017', null, 'ciencia', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'La Tierra gira alrededor del Sol.', '["Verdadero", "Falso"]'::jsonb, 'La Tierra tarda un año en dar una vuelta completa alrededor del Sol.', null, 'KIDS'),
('nin-cie-018', null, 'ciencia', 'OBJECTIVE', 'TRUE_FALSE', 'MEDIUM', false, 'Las plantas fabrican su propio alimento con la luz del sol.', '["Verdadero", "Falso"]'::jsonb, 'Ese proceso se llama fotosíntesis.', null, 'KIDS'),
('nin-cur-006', null, 'curiosidades', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'El chocolate se hace con las semillas del cacao.', '["Verdadero", "Falso"]'::jsonb, 'Las semillas del cacao se secan, se tuestan y se muelen para hacer chocolate.', null, 'KIDS'),
('nin-dep-010', null, 'deportes', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'En un partido de fútbol cada equipo tiene dos arqueros en la cancha.', '["Verdadero", "Falso"]'::jsonb, 'Cada equipo tiene un solo arquero en la cancha.', null, 'KIDS'),
('nin-cie-019', null, 'ciencia', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'El hielo es agua en estado sólido.', '["Verdadero", "Falso"]'::jsonb, 'Cuando el agua se congela se vuelve hielo.', null, 'KIDS'),
('nin-ani-024', null, 'animales', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'Antes de ser mariposas, las mariposas son orugas.', '["Verdadero", "Falso"]'::jsonb, 'La oruga forma una crisálida y de ella sale la mariposa.', null, 'KIDS'),
('nin-num-012', null, 'numeros', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'Un triángulo tiene cuatro lados.', '["Verdadero", "Falso"]'::jsonb, 'El triángulo tiene tres lados.', null, 'KIDS'),
('nin-ani-025', null, 'animales', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'El elefante es el animal más pequeño del mundo.', '["Verdadero", "Falso"]'::jsonb, 'Al contrario: el elefante es el animal terrestre más grande.', null, 'KIDS'),
('nin-mus-006', null, 'musica', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'El violín es un instrumento de cuerda.', '["Verdadero", "Falso"]'::jsonb, 'El violín suena al frotar sus cuerdas con un arco.', null, 'KIDS'),
('nin-his-004', null, 'historia', 'OBJECTIVE', 'TRUE_FALSE', 'MEDIUM', false, 'Simón Bolívar nació en Colombia.', '["Verdadero", "Falso"]'::jsonb, 'Simón Bolívar nació en Caracas, Venezuela, en 1783.', null, 'KIDS'),
('nin-cul-006', null, 'cultura', 'OBJECTIVE', 'TRUE_FALSE', 'EASY', false, 'La Navidad se celebra el 25 de diciembre.', '["Verdadero", "Falso"]'::jsonb, 'El 25 de diciembre es Navidad.', null, 'KIDS'),
('nin-ani-026', null, 'animales', 'OBJECTIVE', 'TRUE_FALSE', 'MEDIUM', false, 'El colibrí es una de las aves más pequeñas del mundo.', '["Verdadero", "Falso"]'::jsonb, 'Algunos colibríes pesan menos que una moneda, y Colombia es uno de los países con más especies.', null, 'KIDS')
